"use strict";(self.webpackChunkivoai_documentation=self.webpackChunkivoai_documentation||[]).push([[9352],{72988(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>o,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"native-graft","title":"Native Graft code intelligence","description":"IVOAI owns local code inspection, its authorization and its resource budget. Graft","source":"@site/../docs/native-graft.md","sourceDirName":".","slug":"/native-graft","permalink":"/docs/next/native-graft","draft":false,"unlisted":false,"editUrl":"https://github.com/ivo-lopes/ivoai/edit/main/../docs/native-graft.md","tags":[],"version":"current","frontMatter":{},"sidebar":"product","previous":{"title":"Remote MCP for ChatGPT and Claude","permalink":"/docs/next/mcp-web"},"next":{"title":"Native Skills and Capability Control Plane","permalink":"/docs/next/skill-control-plane"}}');var a=t(94686),s=t(23629);const r={},o="Native Graft code intelligence",d={},c=[{value:"Managed implementation and lifecycle",id:"managed-implementation-and-lifecycle",level:2},{value:"Choosing the smallest sufficient inspection",id:"choosing-the-smallest-sufficient-inspection",level:2},{value:"Scope, snapshots and coverage",id:"scope-snapshots-and-coverage",level:2},{value:"Runtime limits and failure behavior",id:"runtime-limits-and-failure-behavior",level:2},{value:"Fidelity and operational evidence",id:"fidelity-and-operational-evidence",level:2},{value:"Measured efficiency",id:"measured-efficiency",level:2},{value:"Economic runtime candidate",id:"economic-runtime-candidate",level:3}];function l(e){const n={a:"a",code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"native-graft-code-intelligence",children:"Native Graft code intelligence"})}),"\n",(0,a.jsxs)(n.p,{children:["IVOAI owns local code inspection, its authorization and its resource budget. Graft\nis a replaceable structural library behind ",(0,a.jsx)(n.code,{children:"CodeIntelligenceProvider"}),"; it does not\nown the session, choose an executor or become a second knowledge server. The\ninstitutional source order remains ",(0,a.jsx)(n.strong,{children:"Memory \u2192 Context"}),". Compiler and test results\nremain the evidence for executable behavior."]}),"\n",(0,a.jsx)(n.p,{children:"This page describes the implemented provider, sandbox, gateway and build contract.\nApplication sessions project the capability through the existing authenticated\ngateway. Measured results and remaining acceptance gates belong to the release\nvalidation report; a single provider sample does not establish general savings. Real Claude validation\nremains pending under IVOAI-188 and is not implied by local fixtures or Codex tests."}),"\n",(0,a.jsx)(n.h2,{id:"managed-implementation-and-lifecycle",children:"Managed implementation and lifecycle"}),"\n",(0,a.jsxs)(n.p,{children:["The reviewed upstream is ",(0,a.jsx)(n.code,{children:"trailhq/Graft"})," version ",(0,a.jsx)(n.strong,{children:"0.21.1"}),", commit\n",(0,a.jsx)(n.code,{children:"fe30ead39d5e6f0c921018d364da2bdbc9d4b3ad"}),", under the MIT license. IVOAI's managed\nidentity is ",(0,a.jsx)(n.strong,{children:"0.21.1-ivoai.1"}),". Its source tar SHA-256 is\n",(0,a.jsx)(n.code,{children:"d39598390324ad0076a88ab593b63ad2ba352370ea07c073e31f11327979f8e1"}),";\nthe npm lock SHA-256 is\n",(0,a.jsx)(n.code,{children:"c05064ea18ed1b538e27cc788f1d6ea2cae00b2c00c79ef552fc1bb4c54fd5f5"}),"."]}),"\n",(0,a.jsxs)(n.p,{children:["The upstream repository was renamed to ",(0,a.jsx)(n.code,{children:"trailhq/Trail-Code"}),". The reviewed source\narchive changes only its root directory prefix; the pinned commit and all 391\nnormalized entries retain identical contents, modes and links. The v0.12.0\narchive hash remains recorded in the historical validation report."]}),"\n",(0,a.jsxs)(n.p,{children:["The release build installs locked dependencies with lifecycle scripts disabled,\ncompiles the ten native bindings explicitly with managed Node ",(0,a.jsx)(n.strong,{children:"26.11.1"})," headers,\nand builds the viewer and grammar queries. The native compatibility patch changes two\n",(0,a.jsx)(n.code,{children:"tree-sitter@0.21.1"})," C++17 flags to C++20 for those headers. Compilation uses a\nnetwork-isolated bubblewrap environment; runtime isolation is the Go sandbox\ndescribed below. CI selects GCC 12 on native Linux amd64 and arm64 runners. The\namd64 compiler flags exclude AVX/AVX2; QEMU Nehalem exercises the actual Node and\nlibrary, including native and WASM grammars."]}),"\n",(0,a.jsxs)(n.p,{children:["Packaging refuses native bindings requiring more than ",(0,a.jsx)(n.strong,{children:"GLIBC 2.35"}),",\n",(0,a.jsx)(n.strong,{children:"GLIBCXX 3.4.30"})," or ",(0,a.jsx)(n.strong,{children:"CXXABI 1.3.13"}),". Compiler selection alone is not a passing\ncompatibility result. The archive contains the compiled library, runtime\ndependencies, viewer/query assets, licenses, dependency integrity inventory,\nper-file SHA-256 values, ABI evidence and build provenance. Release metadata binds\nsource, reviewed build inputs and the resulting archive digest to the immutable\ncomponent identity. Native architecture, ABI and no-AVX gates must pass in CI;\nthe local GCC 14 experiment was correctly rejected by the ABI gate."]}),"\n",(0,a.jsxs)(n.p,{children:["The managed application path requires no separate Graft activation,\nupstream CLI installation or manual project initialization. A release carrying the\nreviewed metadata participates in normal ",(0,a.jsx)(n.code,{children:"ivoai setup"}),", ",(0,a.jsx)(n.code,{children:"ivoai update"})," and managed\ncomponent promotion/rollback. See ",(0,a.jsx)(n.a,{href:"/docs/next/update-rollback",children:"Update and rollback"}),".\nDevelopment builds without that metadata report Graft unavailable instead of\ninstalling an unreviewed substitute. An ambient ",(0,a.jsx)(n.code,{children:"graft"})," executable is not adopted.\nThe packaged IVOAI ",(0,a.jsx)(n.code,{children:"graft-runtime"})," accepts only ",(0,a.jsx)(n.code,{children:"--version"}),"; actual operations use\nthe private Go-owned adapter. Personal provider configurations and credentials are\nnot modified or imported."]}),"\n",(0,a.jsx)(n.h2,{id:"choosing-the-smallest-sufficient-inspection",children:"Choosing the smallest sufficient inspection"}),"\n",(0,a.jsxs)(n.p,{children:["The host capability is ",(0,a.jsx)(n.code,{children:"code_inspect"}),". It supports bounded symbol search, literal\noccurrences, file API inspection, callers, repository maps, impact analysis,\nfreshness checks, explicit builds and private visualization exports. Native\n",(0,a.jsx)(n.code,{children:"graft_find_code"}),", ",(0,a.jsx)(n.code,{children:"graft_find_all"}),", ",(0,a.jsx)(n.code,{children:"graft_trace_calls"}),", ",(0,a.jsx)(n.code,{children:"graft_file_api"}),",\n",(0,a.jsx)(n.code,{children:"graft_repo_map"})," and ",(0,a.jsx)(n.code,{children:"graft_check_freshness"})," aliases remain scoped by the same gateway.\nThey do not expose an upstream MCP server or allow callers to choose another root,\norganization or permissions scope."]}),"\n",(0,a.jsx)(n.p,{children:"Automatic inspection can answer a literal search directly. For API inspection of\nan identified small file, it can return the complete file when it fits within half\nthe requested result budget. Relations and larger structural questions use Graft.\nAn unambiguous Go declaration, verified by the standard Go parser, can also use a\nshort direct excerpt. A warm graph alone does not force another Node process;\nan existing exact-query cache is revalidated before reuse. The implementation and\nfile-API MCP aliases use this same selection; grouped search retains structural\ngrouping. Each alias advertises only its operation's parameters.\nThis routing avoids a structural subprocess when exact local\nevidence is already sufficient. Eligibility checks precede cost ranking. Bounded\nlocal measurements update latency and result-size estimates by operation; missing\nCPU, memory or token measurements remain unknown. Bytes divided by four is an\nexplicit token estimate, never provider accounting. At most 18 aggregate rows are\nstored per repository/worktree/organization/permission identity; queries and\nsource content are not stored in this cost history.\nA conservative task classifier can prefetch bounded code evidence; it neither\ngrants capabilities nor replaces institutional Memory/Context research.\nWorkers receive only their own scoped evidence after Skill Gate admission. For a\nready primary-owned task, the approved plan or subsequent wait response can carry\nthe same exact artifact-backed evidence automatically. Each task is delivered at\nmost once per bridge process; worker evidence is not copied to the primary.\nThe aggregate primary evidence envelope is limited to 4,096 bytes and retrieval\nto 20 seconds per response. Revoked admission discards pending evidence. A failure\nreturns a sanitized degraded indicator, allowing permitted fallback inspection.\nExplicit native tool restrictions and required-skill denials also constrain\nprefetch. Raw evidence stays out of persisted plans, checkpoints and event logs."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.code,{children:"deep"}),"/LLM enrichment and LSP subprocesses are disabled until there is a safe,\nreviewed integration through official clients. The adapter performs graph-only\nbuilds, with no cloud wiring, repository hooks, provider configuration loading or\nupstream CLI initialization. Missing structural evidence stays missing; a literal\nmatch does not prove a call relationship or complete impact analysis."]}),"\n",(0,a.jsx)(n.h2,{id:"scope-snapshots-and-coverage",children:"Scope, snapshots and coverage"}),"\n",(0,a.jsx)(n.p,{children:"The host supplies the canonical worktree root, organization/knowledge scope and\npermission identity. All three bind the private cache key; absent trusted scope\nis rejected. Repository text, tool arguments and organization-like directory names\ncannot grant authority. Different worktrees or permission scopes do not share an\nindex merely because they contain the same Git revision."}),"\n",(0,a.jsx)(n.p,{children:"Inventory uses Git's tracked and non-ignored untracked files, with hooks and\nfsmonitor disabled and no global/system Git configuration. Nested repositories\nremain separate. Only admitted source extensions and recognized project manifests enter the inventory;\nhidden paths, dependencies, build/output directories, generated hashed/minified\nJavaScript bundles, non-regular files and oversized files are excluded. Unsupported\nlanguages, excluded generated sources and large files are outside coverage. An\ninventory count is not a claim that every file received structural extraction."}),"\n",(0,a.jsxs)(n.p,{children:["The host reads bounded exact bytes through ",(0,a.jsx)(n.code,{children:"os.Root"}),", checks paths and file types,\nand copies those bytes into a private snapshot. Graft receives that snapshot,\nnever a write grant to the original repository. Source digests, adapter identity\nand immutable managed object identity govern freshness and result reuse. Receipts also validate the\ncomplete index tree, including extraction-cache sidecars, before reusing an index; invalid cache evidence causes rebuilding.\nQuery results are bounded to 64 cached entries per source generation. Repository\ntext and cached results remain untrusted data, not instructions or authorization."]}),"\n",(0,a.jsx)(n.h2,{id:"runtime-limits-and-failure-behavior",children:"Runtime limits and failure behavior"}),"\n",(0,a.jsxs)(n.table,{children:[(0,a.jsx)(n.thead,{children:(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.th,{children:"Boundary"}),(0,a.jsx)(n.th,{children:"Enforced limit"})]})}),(0,a.jsxs)(n.tbody,{children:[(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Source inventory"}),(0,a.jsx)(n.td,{children:"20,000 files"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Individual source"}),(0,a.jsx)(n.td,{children:"1,000,000 bytes"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Total source snapshot"}),(0,a.jsx)(n.td,{children:"128 MiB"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Result text"}),(0,a.jsx)(n.td,{children:"At most 32 KiB; a request can choose a smaller budget"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"V8 old-space heap"}),(0,a.jsx)(n.td,{children:"256 MiB"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Process RSS"}),(0,a.jsx)(n.td,{children:"512 MiB threshold, monitored at 20 ms intervals"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Structural request"}),(0,a.jsx)(n.td,{children:"90 seconds, including admitted waiting time"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Structural processes"}),(0,a.jsx)(n.td,{children:"One active process per shared cache root"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Admission queue"}),(0,a.jsx)(n.td,{children:"Eight total admitted requests, including the active request"})]})]})]}),"\n",(0,a.jsx)(n.p,{children:"The RSS threshold is monitored cancellation, not a promise of a byte-exact kernel\nmemory ceiling. Timeout, cancellation, memory excess and queue saturation produce\nbounded failures. A build reporting parser or index errors is rejected rather\nthan presenting a partial graph as complete evidence. Missing metrics are not replaced with zero or invented values."}),"\n",(0,a.jsx)(n.p,{children:"The disposable runtime helper applies Landlock and seccomp before Node starts.\nIt permits reads of the managed distribution, source snapshot and necessary shared\nlibraries, and writes only to the private index directory. Network access and new\nchild processes are denied; Node's required threads remain permitted. The child\nhas a minimal environment, no personal HOME/configuration grants, no provider\ncredentials and no inherited connected sockets. Unsupported platforms or missing\nkernel protections fail closed; the adapter does not retry without isolation.\nThe runtime requires Linux amd64/arm64 and Landlock ABI 1 or newer. ABI 1/2\nreceive additional seccomp truncation restrictions; there is no unsandboxed fallback."}),"\n",(0,a.jsx)(n.p,{children:"The existing authenticated capability gateway owns session admission and tool\ngrants. Provider unavailability can select permitted direct inspection when it\nanswers the question, or an explicit unavailable result. It never broadens the\nfilesystem or authorization scope."}),"\n",(0,a.jsx)(n.h2,{id:"fidelity-and-operational-evidence",children:"Fidelity and operational evidence"}),"\n",(0,a.jsxs)(n.p,{children:["Code observations use fidelity class ",(0,a.jsx)(n.strong,{children:(0,a.jsx)(n.code,{children:"exact_required"})}),". They record only\noperational facts such as provider/routing reason, duration, result bytes,\ntruncation, cache hit, index freshness, source/index counts and measured CPU/peak\nRSS when available. Cache hits do not inherit CPU/RSS measurements from an earlier\nprocess. Queries, filenames, source text, source hashes, arbitrary errors and\nexported artifact contents are excluded from observation events."]}),"\n",(0,a.jsx)(n.p,{children:"Token usage and savings remain unavailable without actual evidence. The adapter\nremoves upstream theoretical token-saving annotations; result-byte counts are not\ntoken measurements. Console diagnostics preserve unknown/unavailable states.\nA private visualization is an inspectable artifact, not proof of complete code\ncoverage or executable correctness."}),"\n",(0,a.jsx)(n.p,{children:"The implemented fixtures cover scope identity, bounded snapshots, freshness,\ncorruption handling, routing, adapter calls, observations and sandbox denial.\nRelease builds additionally require native grammar/viewer smoke, ABI checks and\nthe no-AVX gate. Full integration, benchmark acceptance and real-client results\nmust be recorded by the candidate's final validation report; pending work must not\nbe inferred as complete from this architecture description."}),"\n",(0,a.jsx)(n.h2,{id:"measured-efficiency",children:"Measured efficiency"}),"\n",(0,a.jsx)(n.h3,{id:"economic-runtime-candidate",children:"Economic runtime candidate"}),"\n",(0,a.jsxs)(n.p,{children:["The next candidate narrows automatic turn/worker discovery to ",(0,a.jsx)(n.code,{children:"code_inspect"}),"\nunless native operation names are explicitly requested. Single-signature API\nrequests use the implementation lookup contract; a known-file API request uses\nthe file-API contract. Mixed relationship/impact requests retain the facade. Pure institutional\nrequests omit the code transport in AUTO; ambiguous requests retain the facade.\nAll nine local operations remain implemented. Explicit worker allowlists still\ntake precedence, including an empty deny list. Automatic worker evidence cannot\nbypass an exact tool restriction. Native direct sessions retain the existing\nfull discovery contract because their task is not known at launch."]}),"\n",(0,a.jsxs)(n.p,{children:["Schema selection is fixed before client startup. Execution admission remains\nindependent and is checked for every call; pre-plan discovery does not grant\npermission. The ",(0,a.jsx)(n.code,{children:"tool.projection"})," event measures available/presented tool counts\nand serialized schema bytes without saving tool definitions or arguments. The\nOpenCode diagnostic shows these observations and reports token attribution as\nunknown. Fewer schema bytes alone do not prove lower provider usage."]}),"\n",(0,a.jsx)(n.p,{children:"Small known-file inspection reads only the authorized file after checking Git\ninventory membership; its source digest covers that file, not unrelated sources.\nExact Go declarations include the parsed package name, rather than inferring it\nfrom the directory, and are returned in full when they fit the result budget,\notherwise explicitly marked as excerpts. Ambiguous natural-language references\ndo not become symbol names. Cost predictions require at least five samples and\nat least 90% successful observations; malformed persisted aggregates leave\nconservative defaults in force. Normalized operations are included in sanitized capability events; tool queries\nand repository content remain excluded. No permission or resource ceiling is increased."}),"\n",(0,a.jsxs)(n.p,{children:["The initial three-repetition schema-projection pilot preserved correctness but\ndid not meet the release efficiency gate. See\n",(0,a.jsx)(n.a,{href:"https://github.com/ivo-lopes/ivoai/blob/fix/economic-runtime/release-notes/economic-runtime-validation.md",children:"candidate validation"}),".\nThe v0.12.0 measurements below remain historical evidence, unchanged."]}),"\n",(0,a.jsx)(n.p,{children:"Two real Codex comparisons, each covering 12 paired scenarios, passed their\ncorrectness checks but increased aggregate tokens and elapsed time when exposing\nstructural MCP tools. The follow-up measured 879,174 versus 1,203,629 input tokens\nand 202,007 versus 278,003 ms. Tool availability alone is not a savings mechanism."}),"\n",(0,a.jsx)(n.p,{children:"A separate test of automatic App prefetch passed all three B cases; two A\nbaseline responses failed strict checks, so the overall benchmark exited 1.\nOnly the correctness-matched API pair supports an efficiency comparison:\n48,163 \u2192 16,129 input tokens and 13,178 \u2192 8,149 ms, with two \u2192 zero model tool\ncalls. This single synthetic sample does not establish general savings."}),"\n",(0,a.jsxs)(n.p,{children:["For 121 source files, ten warm structural queries hit cache with p95 9 ms against\na 100-ms target. Cold build took 4,241 ms; edit/rename/delete updates took\n628/767/744 ms, with peak observed RSS 109,203,456 bytes. See the\n",(0,a.jsx)(n.a,{href:"https://github.com/ivo-lopes/ivoai/blob/v0.12.0/release-notes/graft-native-validation.md",children:"validation record and raw measurements"}),"\nfor test revisions, scope and limitations. No unfavorable sample is omitted."]})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},23629(e,n,t){t.d(n,{R:()=>r,x:()=>o});var i=t(92990);const a={},s=i.createContext(a);function r(e){const n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);